DROP TABLE IF EXISTS `recipes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recipes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL,
  `description` text,
  `cooking_time` int unsigned DEFAULT NULL COMMENT '总耗时（分钟）',
  `cuisine_id` int unsigned DEFAULT NULL,
  `season_id` int unsigned DEFAULT NULL,
  `taste_id` int unsigned DEFAULT NULL,
  `difficulty_id` int unsigned DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL COMMENT '关联 users 表，允许 NULL 表示匿名',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `season_id` (`season_id`),
  KEY `taste_id` (`taste_id`),
  KEY `difficulty_id` (`difficulty_id`),
  KEY `created_by` (`created_by`),
  KEY `idx_filter` (`cuisine_id`,`taste_id`,`season_id`),
  CONSTRAINT `recipes_ibfk_1` FOREIGN KEY (`cuisine_id`) REFERENCES `cuisine` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `recipes_ibfk_2` FOREIGN KEY (`season_id`) REFERENCES `season` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `recipes_ibfk_3` FOREIGN KEY (`taste_id`) REFERENCES `taste` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `recipes_ibfk_4` FOREIGN KEY (`difficulty_id`) REFERENCES `difficulty` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `recipes_ibfk_5` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
