INSERT INTO `steps` VALUES (1,1,1,'豆腐切块，冷水下锅加盐焯水',120),(2,1,2,'牛肉馅炸酥捞出',180),(3,1,3,'锅中放油，加入豆瓣酱炒出红油',60),(4,1,4,'加入豆腐和适量水，小火炖5分钟',300),(5,1,5,'撒花椒粉，出锅装盘',30),(33,5,1,'排骨冷水下锅，加入姜片和料酒，焯水去血沫，捞出沥干。',480),(34,5,2,'锅中放少许油，加入冰糖，小火炒至枣红色，下排骨快速翻炒上色。',300),(35,5,3,'加入生抽、老抽、葱段、八角，翻炒均匀后加入水，大火烧开转小火慢炖40分钟。',2400),(36,5,4,'开大火收汁，至汤汁浓稠包裹排骨，即可出锅装盘。',180),(37,2,1,'番茄切块，鸡蛋打散',60),(38,2,2,'锅中放油，先炒鸡蛋盛出',120),(39,2,3,'再炒番茄出汁，加入鸡蛋翻炒',180),(40,2,4,'加盐调味，撒葱花出锅',30),(41,6,1,'草鱼处理干净，片成鱼片，鱼骨切块。鱼片用鸡蛋清、淀粉、料酒、少许盐和白胡椒粉抓匀腌制15分钟。',900),(42,6,2,'酸菜切段，姜蒜切片，葱切段，干辣椒剪成小段。',180),(43,6,3,'锅中倒油烧热，下姜片、蒜片、葱段爆香，加入酸菜翻炒出香味。',180),(44,6,4,'加入鱼骨块翻炒至变色，倒入足量开水（约1500毫升），大火煮开后转中火煮10分钟至汤色发白。',600),(45,6,5,'将鱼骨和酸菜捞出铺在大碗底部，锅中留汤。汤再次烧开，下入腌好的鱼片，用筷子轻轻拨散，煮至鱼片变白（约30秒）立即关火。',60),(46,6,6,'将鱼片和汤倒入装有酸菜和鱼骨的碗中。',30),(47,6,7,'另起锅烧热油（约30毫升），放入干辣椒段和花椒炸香，迅速泼在鱼片上，撒上葱花即可。',120),(48,7,1,'豆腐切2厘米方块，开水加盐焯烫2分钟，捞出沥干',180),(49,7,2,'锅中倒油烧热，下猪肉末炒至变色，加豆瓣酱炒出红油',120),(50,7,3,'放入姜蒜末炒香，加200毫升清水烧开，滑入豆腐，小火煮5分钟',300),(51,7,4,'淋入水淀粉勾芡，撒花椒粉和葱花，翻匀出锅',60),(52,8,1,'牛肉片加蛋清、淀粉、少许盐抓匀腌制15分钟',900),(53,8,2,'锅中水烧开，下黄豆芽和莴笋叶烫熟，捞出铺碗底',180),(54,8,3,'另起锅倒油，小火炒香豆瓣酱、姜片，加水烧开，下牛肉片滑熟，连汤倒入菜碗',600),(55,8,4,'撒上蒜末、干辣椒段、花椒，淋上滚烫热油激出香味',60),(56,9,1,'鸡块加料酒、生抽、淀粉抓匀腌制20分钟',1200),(57,9,2,'锅中宽油烧至六成热，下鸡块中火炸至金黄酥脆，捞出沥油',480),(58,9,3,'锅留底油，小火炒香干辣椒、花椒、姜蒜葱，出红油',180),(59,9,4,'放入炸好的鸡块，大火快速翻炒均匀，加少许盐调味，出锅',120),(60,10,1,'鱼片加蛋清、淀粉、少许盐和料酒抓匀腌制15分钟',900),(61,10,2,'水烧开，下黄豆芽烫熟，捞出铺大碗底',180),(62,10,3,'锅中倒油，小火炒香豆瓣酱和姜片，加足量水烧开，滑入鱼片煮2分钟，连汤倒入菜碗',540),(63,10,4,'撒上蒜末、干辣椒、花椒，淋上滚烫热油，激出香味即可',60),(64,11,1,'鸭血和毛肚分别焯水30秒，捞出沥干',60),(65,11,2,'水烧开，下黄豆芽烫熟，捞出铺大碗底',180),(66,11,3,'锅倒油，小火炒香豆瓣酱、姜片，加水烧开，放入鸭血、午餐肉煮3分钟，再下毛肚烫30秒，连汤倒入菜碗',480),(67,11,4,'撒上蒜末、干辣椒、花椒，淋上滚烫热油，激出香味',60),(68,12,1,'锅中加水，放入姜片、葱段和料酒，大火煮沸',180),(69,12,2,'将基围虾倒入沸水中，煮至虾身变红弯曲，约2-3分钟',150),(70,12,3,'捞出虾，沥干水分，摆盘；小碗中混合生抽和花生油作为蘸料',60),(71,13,1,'鱼身两面各划三刀，抹少许盐，鱼腹塞入姜丝和葱段，上蒸盘',120),(72,13,2,'蒸锅水烧开后，放入鱼盘，大火蒸8-10分钟',540),(73,13,3,'取出鱼盘，倒掉盘中汤汁，铺上新鲜葱姜丝，淋上蒸鱼豉油，再浇上烧热的花生油',60),(74,15,1,'热锅冷油，大火快炒牛肉片至变色，盛出备用',120),(75,15,2,'锅中再加少许油，放入河粉，用筷子拨散，中火煎至微黄',180),(76,15,3,'加入豆芽、韭黄、葱段和牛肉，淋